"""Disk-usage accounting for sink files."""

import os

from . import _winapi as w32
from ._winapi import is_windows
from .errors import WSParseError


def _round_up(value, cluster):
    if value <= 0 or cluster <= 1:
        return max(value, 0)
    remainder = value % cluster
    if remainder == 0:
        return value
    return value + (cluster - remainder)


def _disk_usage_fallback(path):
    """Best-effort occupancy off Windows, from ``st_blocks`` when available."""
    try:
        info = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    if os.path.isdir(path) or not os.path.isfile(path):
        raise w32.unsupported(path, "not a regular file, so it cannot be a sparse file")
    blocks = getattr(info, "st_blocks", None)
    if blocks is None:
        return info.st_size
    return int(blocks) * 512


def disk_usage(path):
    """Return the number of bytes ``path`` really occupies on disk.

    This is what the quota tracker subtracts from the volume budget, so it
    describes the clusters the sink actually holds -- not the number of bytes a
    reader would see.  For a sparse sink the holes cost nothing, so the value
    can be far below the logical length; for a dense file the two are roughly
    the same.  The value is rounded up to a whole cluster of the volume.

    Raises :class:`WSParseError` with ``kind == "os"`` when the file cannot be
    inspected and ``kind == "unsupported"`` when the object cannot be a sparse
    file at all (a directory, for instance).
    """
    path = os.fspath(path)
    if not is_windows():
        return _disk_usage_fallback(path)

    w32.reject_non_file(path)
    try:
        used = w32.compressed_file_size(path)
    except WSParseError:
        # Some filters do not implement GetCompressedFileSizeW; fall back to
        # adding up the ranges NTFS says are backed by clusters.
        from .ranges import allocated_ranges

        used = sum(length for _offset, length in allocated_ranges(path))
    return _round_up(int(used), w32.cluster_size(path))

"""Allocated-range reporting for sink files."""

import os

from . import _winapi as w32
from ._winapi import is_windows
from .errors import WSParseError
from .flags import sparse_state


def _normalise(ranges, size):
    """Clamp, sort and merge ``ranges`` so the result is ordered and disjoint."""
    cleaned = []
    for offset, length in ranges:
        offset = int(offset)
        length = int(length)
        if length <= 0 or offset >= size:
            continue
        if offset < 0:
            length += offset
            offset = 0
            if length <= 0:
                continue
        if offset + length > size:
            length = size - offset
        if length > 0:
            cleaned.append((offset, length))
    cleaned.sort(key=lambda item: item[0])
    merged = []
    for offset, length in cleaned:
        if merged and offset <= merged[-1][0] + merged[-1][1]:
            previous_offset, previous_length = merged[-1]
            end = max(previous_offset + previous_length, offset + length)
            merged[-1] = (previous_offset, end - previous_offset)
        else:
            merged.append((offset, length))
    return merged


def _ranges_fallback(path, size):
    """Off Windows there is no portable extent query: report one dense range."""
    return [(0, size)] if size > 0 else []


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is already allocated is on disk, everything else
    is a hole that still needs data.  The answer comes from the file system
    itself (``FSCTL_QUERY_ALLOCATED_RANGES``), so a pre-allocated sink reports
    only what has really been written.

    The list is ordered by ``offset``, the ranges never overlap and every range
    lies inside the file's logical length.  A file that is one big hole reports
    an empty list; a file with no holes reports a single range covering it.
    """
    path = os.fspath(path)
    if not is_windows():
        try:
            size = os.path.getsize(path)
        except OSError as exc:
            raise WSParseError(str(exc), kind="os", path=path) from exc
        return _ranges_fallback(path, size)

    w32.reject_non_file(path)
    with w32.open_handle(path) as handle:
        size = w32.file_size(handle)
        if size == 0:
            return []
        try:
            found = w32.query_allocated_ranges(handle, size)
        except WSParseError as exc:
            # A volume that does not implement the extent query cannot hold
            # holes either, so everything in the file is allocated.  Only
            # report that for a file we know is not sparse.
            if exc.kind == "unsupported" and not sparse_state(path):
                return [(0, size)]
            raise
    return _normalise(found, size)

