"""Disk-usage accounting for sink files."""

import os

from . import _winapi as w32
from ._winapi import is_windows
from .errors import WSParseError
from .ranges import _normalise


def _round_up(value, cluster):
    if value <= 0:
        return 0
    if cluster <= 1:
        return value
    remainder = value % cluster
    if remainder == 0:
        return value
    return value + (cluster - remainder)


def _disk_usage_fallback(path):
    """Best-effort occupancy off Windows, from ``st_blocks`` when available."""
    try:
        info = os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    if os.path.isdir(path) or not os.path.isfile(path):
        raise w32.unsupported(path, "not a regular file, so it cannot be a sparse file")
    blocks = getattr(info, "st_blocks", None)
    if blocks is None:
        return info.st_size
    return int(blocks) * 512


def disk_usage(path):
    """Return the number of bytes ``path`` really occupies on disk.

    This is what the quota tracker subtracts from the volume budget, so it
    describes the clusters the sink actually holds -- not the number of bytes a
    reader would see.  For a sparse sink the holes cost nothing, so the value
    can be far below the logical length; for a dense file the two are roughly
    the same.  The value is rounded up to a whole cluster of the volume.

    The figure comes from the ranges NTFS reports as backed by clusters, which
    keeps it consistent with :func:`~wsparse.allocated_ranges`.  When the file
    is stored compressed, the smaller footprint reported by the file system is
    preferred, because that is what the volume really gives up.

    Raises :class:`WSParseError` with ``kind == "os"`` when the file cannot be
    inspected and ``kind == "unsupported"`` when the object cannot be a sparse
    file at all (a directory, for instance).
    """
    path = os.fspath(path)
    if not is_windows():
        return _disk_usage_fallback(path)

    w32.reject_non_file(path)
    cluster = w32.cluster_size(path)

    with w32.open_handle(path) as handle:
        size = w32.file_size(handle)
        if size == 0:
            return 0
        extents = None
        try:
            extents = _normalise(w32.query_allocated_ranges(handle, size), size)
        except WSParseError:
            extents = None
        try:
            allocated = w32.allocation_size(handle)
        except WSParseError:
            allocated = None

    try:
        compressed = w32.compressed_file_size(path)
    except WSParseError:
        compressed = None

    if extents is not None:
        used = _round_up(sum(length for _offset, length in extents), cluster)
        # A compressed stream occupies less than its extents suggest; trust the
        # smaller number, but never a bogus zero for a file that has extents.
        if compressed and compressed < used:
            used = _round_up(compressed, cluster)
        return used

    for candidate in (compressed, allocated):
        if candidate:
            return _round_up(candidate, cluster)
    if allocated == 0 or compressed == 0:
        return 0
    raise w32.unsupported(path, "the volume does not report on-disk occupancy")

